    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);

        bool reverted;
        bool retval;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            retval = r;
        } catch {
            reverted = true;
            retval = false;
        }

        // Assert: either _tos is empty and the call reverted, or _tos is non-empty and if it did not revert it returned true.
        // (A implies B) is expressed as (!A || B). Here: (_tos.length > 0) implies (!reverted ? retval == true : true)
        // Simpler equivalent: (_tos.length == 0 && reverted) || (_tos.length > 0 && (!reverted && retval)) || (_tos.length > 0 && reverted)
        // Which simplifies to: (_tos.length == 0 && reverted) || (_tos.length > 0 && (reverted || retval))
        assert((_tos.length == 0 && reverted) || (_tos.length > 0 && (reverted || retval)));
    }

    receive() external payable { }
}

